import channels from './channels.json';

export interface PodcastVideo {
  id: string;
  title: string;
  duration: number;
}

export interface PodcastChannel {
  id: string;
  handle: string;
  name: string;
  channelId: string;
  url: string;
  description: string;
  avatarUrl: string;
  videos: PodcastVideo[];
}

export const PODCAST_CHANNELS: PodcastChannel[] = channels;

export function podcastVideoPath(videoId: string) {
  return `/podcast?v=${encodeURIComponent(videoId)}`;
}

export function podcastDuration(seconds: number) {
  const total = Math.floor(seconds);
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  return `${hours ? `${hours}:${String(minutes).padStart(2, '0')}` : minutes}:${String(total % 60).padStart(2, '0')}`;
}
